<?php
require_once __DIR__.'/config.php';require_once __DIR__.'/functions.php';require_login();$role=current_user_role($pdo);$uid=(int)$_SESSION['user_id'];$isManager=in_array($role,['admin','editor'],true);
$base=$isManager?'':' WHERE user_id=:uid';$params=$isManager?[]:[':uid'=>$uid];
$stats=[];
foreach(['All posts'=>null,'Published'=>'published','Drafts'=>'draft'] as $label=>$status){
    $sql='SELECT COUNT(*) FROM posts'.($isManager?'':' WHERE user_id=:uid');
    if($status!==null)$sql.=($isManager?' WHERE ':' AND ').'status=:status';
    $q=$pdo->prepare($sql);$queryParams=$params;if($status!==null)$queryParams[':status']=$status;$q->execute($queryParams);$stats[$label]=(int)$q->fetchColumn();
}
$userCount=$role==='admin'?(int)$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn():null;
$sql='SELECT p.id,p.title,p.category,p.status,p.created_at,u.username FROM posts p JOIN users u ON u.id=p.user_id'.($isManager?'':' WHERE p.user_id=:uid').' ORDER BY p.updated_at DESC LIMIT 8';$recent=$pdo->prepare($sql);$recent->execute($params);$rows=$recent->fetchAll();
$notice='';foreach(['created'=>'Post created.','updated'=>'Post updated.','deleted'=>'Post deleted.'] as $key=>$msg)if(isset($_GET[$key]))$notice=$msg;
?>
