<div class="stat-grid"><article class="stat-card"><span>All posts</span><strong><?=number_format($stats['All posts'])?></strong><small>Stories in your workspace</small></article><article class="stat-card"><span>Published</span><strong><?=number_format($stats['Published'])?></strong><small>Visible on the blog</small></article><article class="stat-card"><span>Drafts</span><strong><?=number_format($stats['Drafts'])?></strong><small>Waiting to be published</small></article><?php if($userCount!==null):?><article class="stat-card"><span>Members</span><strong><?=number_format($userCount)?></strong><small>Registered accounts</small></article><?php endif;?></div>
